/**
 * Build the Edge Worker.
 *
 * 1. Regenerate edge/assembly/crawlers-config.ts from config/crawlers.json,
 *    so the worker compiles in exactly the crawler list the plugin ships.
 *    The generated file is committed so `npm run test:edge` and the
 *    simulator work without a build; a test fails when it is stale.
 * 2. Compile edge/assembly/index.ts with the AssemblyScript compiler using
 *    the flags the SDK README requires (`--runtime stub`) and recommends
 *    for release builds. Output lands in edge/build/, which is gitignored.
 */

import { execFileSync } from 'node:child_process';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const edgeDir = dirname( fileURLToPath( import.meta.url ) );
const projectRoot = resolve( edgeDir, '..' );
const nodeModules = resolve( projectRoot, 'node_modules' );
const asc = resolve( nodeModules, '.bin/asc' );

/**
 * Render crawlers.json as an AssemblyScript/TypeScript module.
 *
 * Keys are sorted so classification order is stable and matches the
 * plugin's sorted declared set. Patterns are kept verbatim; matching
 * lowercases at runtime.
 *
 * @param {string} json Raw contents of config/crawlers.json.
 * @return {string} Module source.
 */
export function renderCrawlerConfig( json ) {
	const config = JSON.parse( json );
	const version = Number.parseInt( config.version, 10 );
	if ( ! Number.isInteger( version ) || version < 0 ) {
		throw new Error( 'config/crawlers.json: "version" must be an integer' );
	}
	const keys = Object.keys( config.segments ).sort();
	const quote = ( value ) =>
		"'" +
		String( value ).replace( /\\/g, '\\\\' ).replace( /'/g, "\\'" ) +
		"'";
	const lines = [
		'/**',
		' * GENERATED by edge/build.mjs from config/crawlers.json. Do not edit.',
		' *',
		' * Run `npm run edge:build` after changing the JSON file.',
		' */',
		'',
		'export const CRAWLER_VERSION: i32 = ' + version + ';',
		'',
		'export const CRAWLER_KEYS: string[] = [',
		...keys.map( ( key ) => '\t' + quote( key ) + ',' ),
		'];',
		'',
		'export const CRAWLER_PATTERNS: string[][] = [',
	];
	for ( const key of keys ) {
		const patterns = config.segments[ key ].user_agents;
		if ( ! Array.isArray( patterns ) ) {
			throw new Error(
				'config/crawlers.json: "' +
					key +
					'.user_agents" must be an array'
			);
		}
		lines.push( '\t[' );
		for ( const pattern of patterns ) {
			lines.push( '\t\t' + quote( pattern ) + ',' );
		}
		lines.push( '\t],' );
	}
	lines.push( '];', '' );
	return lines.join( '\n' );
}

/**
 * Write the generated module and run the project formatter on it, so the
 * committed copy is always lint-clean regardless of how prettier chooses
 * to wrap the arrays.
 */
function generateCrawlerConfig() {
	const json = readFileSync(
		resolve( projectRoot, 'config/crawlers.json' ),
		'utf8'
	);
	const target = resolve( edgeDir, 'assembly/crawlers-config.ts' );
	writeFileSync( target, renderCrawlerConfig( json ) );
	execFileSync(
		resolve( nodeModules, '.bin/wp-scripts' ),
		[ 'format', target ],
		{
			cwd: projectRoot,
			stdio: 'ignore',
		}
	);
}

/**
 * Compile the worker.
 */
function compile() {
	const buildDir = resolve( edgeDir, 'build' );
	mkdirSync( buildDir, { recursive: true } );

	// NODE_OPTIONS can carry loaders that break asc; the SDK examples drop it.
	const { NODE_OPTIONS: _drop, ...env } = process.env;

	execFileSync(
		asc,
		[
			resolve( edgeDir, 'assembly/index.ts' ),
			'--outFile',
			resolve( buildDir, 'release.wasm' ),
			'--textFile',
			resolve( buildDir, 'release.wat' ),
			'--runtime',
			'stub',
			'--optimizeLevel',
			'3',
			'--shrinkLevel',
			'2',
			'--path',
			nodeModules,
		],
		{ cwd: nodeModules, env, stdio: 'inherit' }
	);
}

const invokedDirectly =
	process.argv[ 1 ] &&
	resolve( process.argv[ 1 ] ) === fileURLToPath( import.meta.url );

if ( invokedDirectly ) {
	generateCrawlerConfig();
	compile();
}
